    var cortado2 = parseFloat(payload[14].VALOR_MAQUINA_5);
    var cortado3 = parseFloat(payload[16].VALOR_MAQUINA_5);
    var programado1 = parseFloat(payload[11].VALOR_MAQUINA_5);
    var programado2 = parseFloat(payload[13].VALOR_MAQUINA_5);
    var programado3 = parseFloat(payload[15].VALOR_MAQUINA_5);

//11-13-15 programa
//12-14-16 cortado

    // Extrae los valores necesarios para el cálculo
    var numerador = cortado1 + cortado2 + cortado3;
    var denominador = 1 + programado1 + programado2 + programado3;

    // Verifica que el denominador no sea cero para evitar divisiones por cero
    if (denominador !== 0) {
        // Calcula el resultado de la fórmula
