        // Convierte el resultado a un número entero
        var resultadoEntero = Math.round(resultado);

        // Envía el resultado como un número entero al nodo Debug
        node.send({payload: resultadoEntero});
        //node.send({ payload: numerador });
    } else {
        // Si el denominador es cero, muestra una advertencia
        node.warn("El denominador es cero, la división no es posible.");
    }
} else {
    // Si payload no tiene al menos 48 elementos, muestra una advertencia
    node.warn("El payload no tiene suficientes elementos para realizar el cálculo.");
}

