let machineGroup = "1.5";  // Identificador de la máquina
let currentState = '';  // Variable para almacenar el estado actual

// Asignar el estado basado en msg.payload
if (msg.payload === '1' || msg.payload === '17') { 
    currentState = 'AUTO'; 
} else if (msg.payload === '81') { 
    currentState = 'CONTROL'; 
} else if (msg.payload === '50' || msg.payload === '33' || msg.payload === '65' || msg.payload === '24' || msg.payload === '49') { 
    currentState = 'PARADA'; 
} else if (msg.payload === '-1') { 
    currentState = 'APAGADA'; 
}


let date = new Date();
let nowISO = date.toISOString();
let todayDate = nowISO.split('T')[0];  // Obtener la fecha en formato YYYY-MM-DD


// Hora de inicio y fin del día
let startOfDay = new Date(`${todayDate}T00:00:00.000Z`).toISOString();
let oneSecondAfterStartOfDay = new Date(`${todayDate}T00:00:01.000Z`).toISOString();
let almostEndOfDay = new Date(`${todayDate}T23:59:58.000Z`).toISOString();
let endOfDay = new Date(`${todayDate}T23:59:59.999Z`).toISOString();

// Recuperar el historial de estados de la máquina desde el contexto global
let timeline = global.get("timeline15") || {
    "dataItems": [
        {
            "group": machineGroup,
            "data": [
                {
                    "label": "",
                    "data": []
                }
            ]
        }
    ]
};

// Buscar la máquina por su ID
let machine = timeline.dataItems.find(item => item.group === machineGroup);

// Si no hay registros, es la primera vez que se ejecuta o es un nuevo día
if (machine.data[0].data.length === 0) {
    // Agregar los registros iniciales del día
    machine.data[0].data.push({
        "timeRange": [startOfDay, oneSecondAfterStartOfDay],
        "val": "AUTO",  // Valor por defecto, puede ser modificado
        "estado": "finalizado"
    });
    machine.data[0].data.push({
        "timeRange": [almostEndOfDay, endOfDay],
        "val": "AUTO",  // Valor por defecto, puede ser modificado
        "estado": "finalizado"
    });
} else {
    // Verificar si es un nuevo día comparando la fecha del primer registro
    let firstEntryDate = new Date(machine.data[0].data[0].timeRange[0]).toISOString().split('T')[0];

    if (firstEntryDate !== todayDate) {
        // Borrar los registros del día anterior
        machine.data[0].data = [];

        // Agregar el primer y segundo timeRange del día
        machine.data[0].data.push({
            "timeRange": [startOfDay, oneSecondAfterStartOfDay],
            "val": "AUTO",  // Valor por defecto, puede ser modificado
            "estado": "finalizado"
        });
        machine.data[0].data.push({
            "timeRange": [almostEndOfDay, endOfDay],
            "val": "AUTO",  // Valor por defecto, puede ser modificado
            "estado": "finalizado"
        });
    }
}

// Filtrar los registros que no sean los de "inicio de día" ni "fin de día"
let realEntries = machine.data[0].data.filter(entry => 
    entry.timeRange[0] !== startOfDay && entry.timeRange[0] !== almostEndOfDay
);

// Obtener la última entrada de estado real
let lastEntry = realEntries.length > 0 ? realEntries[realEntries.length - 1] : null;

// Actualizar el último timeRange con el estado "enproceso"
if (lastEntry && lastEntry.estado === "enproceso") {
    lastEntry.timeRange[1] = nowISO;  // Actualizar la hora de finalización provisional del último registro
}

// Si es un nuevo estado, cerrar el estado anterior y crear un nuevo registro
if (!lastEntry || lastEntry.val !== currentState) {
    if (lastEntry) {
        lastEntry.estado = "finalizado";  // Marcar el último estado como finalizado
    }
    machine.data[0].data.push({
        "timeRange": [nowISO, nowISO],  // Inicia el nuevo rango de tiempo con la hora actual
        "val": currentState,
        "estado": "enproceso"  // Marcar el nuevo estado como en proceso
    });
}

// Guardar la nueva estructura en el contexto global
global.set("timeline15", timeline);

// Devolver la estructura actualizada
msg.payload = timeline;
return msg;

