const entrada = msg.payload;
const maquinas = [1,2,3,4,5,6];
const salida = [];

// Preparamos un objeto para cada máquina
maquinas.forEach(num => {
    salida[num-1] = { maquina: num };
});

// Para cada campo, lo ponemos en cada máquina
entrada.forEach(campo => {
    maquinas.forEach(num => {
        let valor = campo[`VALOR_MAQUINA_${num}`];

        // Normaliza el nombre del campo
        const campoActual = (campo.CAMPO || "").toUpperCase().trim();

        // --- SOLO para CUTPROGR ---
        if (campoActual === "CUTPROGR" && typeof valor === "string") {
            // Si el valor es del tipo Lxxxxx.yyy --> solo deja Lxxxxx
            const match = valor.match(/^(L\d+)\./);
            if (match) {
                valor = match[1];
            }
            // Si no hay match, lo deja tal cual
        }

        salida[num-1][campo.CAMPO] = valor;
    });
});

// Añadir el campo ESTADO según el valor de MACSTAT
salida.forEach(m => {
    const macstat = +m.MACSTAT;
    if (macstat === 17 || macstat === 1) {
        m.ESTADO = "AUTO";
    } else if (macstat === 81) {
        m.ESTADO = "CONTROL";
    } else if (macstat === 18 || macstat === 24) {
        m.ESTADO = "PARADA";
    } else {
        m.ESTADO = "";
    }
});

