// Valores constantes
const Interior = 252; // en mm
const densidad = 7.65; // en kg/dm³

try {
    // Datos del payload
    const alto = Number(msg.payload.Ancho); // en mm
    const Exterior = Number(msg.payload.COILSIZE); // en mm

    // Validar si el valor de COILSIZE es negativo
    if (Exterior < 0) {
        throw new Error("El valor de COILSIZE es negativo");
    }

    // Convertir las unidades de mm a dm
    const radioExterior = Exterior / 100; // en dm
    const radioInterior = Interior / 100; // en dm
    const altura = alto / 100; // en dm

    // Calcular el volumen del cilindro hueco
    const volumenExterior = Math.PI * Math.pow(radioExterior, 2) * altura;
    const volumenInterior = Math.PI * Math.pow(radioInterior, 2) * altura;
    const volumenHueco = volumenExterior - volumenInterior;

    // Calcular el peso del cilindro hueco
    const peso = volumenHueco * densidad;

    // Convertir el resultado a un número entero
    const peso_bobina = Math.round(peso);

    // Asignar el resultado al payload
    msg.payload = peso_bobina;
    msg.topic = "peso";

} catch (error) {
    // En caso de error, asignar el valor de peso a 0
    msg.payload = 0;
    msg.topic = "peso";
    node.error("Error al calcular el peso: " + error.message, msg);
}

