function verifyData(data) {
    const lotes = [...new Set(data.map(item => item.lote))];

    let allValid = true;
    let invalidLotes = [];
    let validLotes = [];

    lotes.forEach(lote => {
        const items = data.filter(item => item.lote === lote);

        // Verificar anchos máximos y mínimos
        const maxAnchoItem = items.reduce((max, item) => item.ancho > max.ancho ? item : max, items[0]);
        const minAnchoItem = items.reduce((min, item) => item.ancho < min.ancho ? item : min, items[0]);

        const validMax = maxAnchoItem.central === "OK" && maxAnchoItem.lateral === "OK" && maxAnchoItem.culata === "OK";
        const validMin = minAnchoItem.central === "OK" && minAnchoItem.lateral === "OK" && minAnchoItem.culata === "OK";

        if (!validMax || !validMin) {
            // node.warn(Lote ${lote} no cumple con la verificación de anchos.);
            allValid = false;
            invalidLotes.push(lote);
        }

        // Verificar sumatoria de "leidas"
        const sumLeidas = items.reduce((sum, item) => sum + (item.leidas || 0), 0);

        if (sumLeidas <= 0) {
            // node.warn(Lote ${lote} no cumple con la verificación de sumatoria de leídas.);
            allValid = false;
            invalidLotes.push(lote);
        }

if (validMax && validMin && sumLeidas > 0){validLotes.push(lote);}    });

    return { allValid, invalidLotes, validLotes };
}
