function getNewName(originalName) {
    // Si el name ya comienza con "45" y tiene 6 dígitos, devolver el mismo
    if (originalName.startsWith('45') && originalName.length === 6) {
        return originalName;
    }

    // Generar un nuevo name que comience con "45" y tenga 6 dígitos
    let newName = '45' + Math.floor(1000 + Math.random() * 9000); // Genera 4 dígitos aleatorios

    // Almacenar el nuevo name asignado si no existe
    const storedNames = context.get('storedNames') || {};
    if (!storedNames[originalName]) {
        storedNames[originalName] = newName;
        context.set('storedNames', storedNames);
    } else {
        // Si ya existe un name asignado para el original, lo reutilizamos
        newName = storedNames[originalName];
    }

    return newName;
}

