// Define la potencia de transmisión a 1 metro (ajustar según necesidad)
const txPower = -60;

// Define el tiempo máximo de diferencia entre lecturas (2 minutos)
const maxTimeDiff = 120000; // 2 minutos en milisegundos

// Obtén el estado almacenado del contexto del nodo para los iBeacons y trackers
let trackerData = context.get('trackerData') || {};
let iBeaconData = context.get('iBeaconData') || {};

// Procesa el mensaje entrante
if (msg.payload && msg.payload.uplink_message && msg.payload.uplink_message.decoded_payload) {
    const trackerId = msg.payload.end_device_ids.device_id;
    const decodedPayload = msg.payload.uplink_message.decoded_payload;

    // Verifica si hay iBeacons en el mensaje
    if (decodedPayload.iBeacons && decodedPayload.iBeacons.length > 0) {
        // Itera sobre cada iBeacon detectado
        decodedPayload.iBeacons.forEach((iBeacon) => {
            const rssi = iBeacon.RSSI;

            // Verifica que el trackerId sea uno de los trackers definidos
            if (trackers[trackerId]) {
                const currentTime = Date.now();

                // Actualiza los datos del tracker en el contexto del nodo
                trackerData[trackerId] = {
                    lat: trackers[trackerId].lat,
                    lon: trackers[trackerId].lon,
                    distance: getDistance(rssi, txPower),
                    timestamp: currentTime, // Añadir timestamp para controlar cuándo llegaron los datos
                    iBeaconMajor: iBeacon.Major, // Guarda el MAJOR del iBeacon
                    iBeaconMinor: iBeacon.Minor  // Guarda el MINOR del iBeacon
                };

                // Guarda el estado actualizado del tracker en el contexto
                context.set('trackerData', trackerData);

                // Almacena o actualiza la información del iBeacon detectado
                const iBeaconId = `${iBeacon.Major}-${iBeacon.Minor}`;

                if (!iBeaconData[iBeaconId]) {
                    iBeaconData[iBeaconId] = [];
                }

                // Añade los datos del tracker que detectó este iBeacon
                iBeaconData[iBeaconId].push({
                    trackerId: trackerId,
                    lat: trackers[trackerId].lat,
                    lon: trackers[trackerId].lon,
                    distance: getDistance(rssi, txPower),
                    timestamp: currentTime
                });

                // Guarda la información actualizada de los iBeacons en el contexto
                context.set('iBeaconData', iBeaconData);

                // Filtrar las lecturas antiguas que ya no son válidas
                iBeaconData[iBeaconId] = iBeaconData[iBeaconId].filter(data => {
                    return (currentTime - data.timestamp) < maxTimeDiff;
                });

                // Si al menos 2 trackers han detectado este iBeacon, calcula su posición
                if (iBeaconData[iBeaconId].length >= 2) {
                    const distances = {};
                    const selectedTrackers = {};

                    iBeaconData[iBeaconId].forEach((data) => {
                        distances[data.trackerId] = data.distance;
                        selectedTrackers[data.trackerId] = {
                            lat: data.lat,
                            lon: data.lon
                        };
                    });

                    try {
                        // Realiza la interpolación ponderada por distancia
                        const result = weightedInterpolate(selectedTrackers, distances);

                        if (result.position) {
                            const ibeaconPosition = result.position;

                            // Verifica si el resultado de la interpolación es válido
                            if (isValidLatitude(ibeaconPosition.lat) && isValidLongitude(ibeaconPosition.lon)) {
                                // Redondear las coordenadas a 5 decimales
                                const roundedLat = parseFloat(ibeaconPosition.lat.toFixed(5));
                                const roundedLon = parseFloat(ibeaconPosition.lon.toFixed(5));

                                msg.payload = {
                                    name: `iBeacon ${iBeacon.Major}-${iBeacon.Minor}`,
                                    lat: roundedLat,
                                    lon: roundedLon,
                                    Major: iBeacon.Major,
                                    Minor: iBeacon.Minor,
                                    RSSI: iBeacon.RSSI
                                };
                                node.send(msg);
                            } else {
                                msg.payload = {
                                    error: "Calculated coordinates are out of bounds",
                                    ibeaconPosition: ibeaconPosition
                                };
                                node.send(msg);
                            }
                        } else {
                            msg.payload = {
                                error: "No valid iBeacon positions found",
                                distances: distances
                            };
                            node.send(msg);
                        }
                    } catch (err) {
                        msg.payload = {
                            error: "Error during interpolation: " + err.message,
                            distances: distances
                        };
                        node.send(msg);
                    }
                } else {
                    // Si no hay suficientes trackers enviando datos
                    msg.payload = {
                        status: "Waiting for data from at least two trackers"
                    };
                    node.send(msg);
                }
            } else {
                // Manejar el caso donde el trackerId no está en la lista de trackers
                msg.payload = {
                    error: `Unexpected tracker ID: ${trackerId}. Expected one of ${Object.keys(trackers).join(', ')}`
                };
                node.send(msg);
            }
        });
    } else {
        // Manejar el caso donde no se detectan iBeacons
        msg.payload = {
            error: "No iBeacons detected",
            receivedPayload: msg.payload // Imprime el payload recibido para depuración
        };
        node.send(msg);
    }
} else {
    // Manejar el caso donde la estructura del mensaje no sea la esperada
    msg.payload = {
        error: "Decoded payload not available or message structure is incorrect",
        receivedPayload: msg.payload // Imprime el payload recibido para depuración
    };
    node.send(msg);
}

// Función para calcular la distancia a partir del RSSI
function getDistance(rssi, txPower, n = 10) {
    if (rssi > 0) {
        return -1.0;
    }
    if (rssi === 0) {
        return -1.0;
    }
    const difference = txPower - rssi;
    const distance = Math.pow(10, difference / (10 * n));
    return distance;
}

// Función para realizar la interpolación ponderada por distancia
function weightedInterpolate(trackers, distances) {
    let weightedLat = 0, weightedLon = 0, totalWeight = 0;

    Object.keys(trackers).forEach((id) => {
        const tracker = trackers[id];
        const weight = 1 / (distances[id] || 1,2); // Inversa de la distancia como peso

        weightedLat += tracker.lat * weight;
        weightedLon += tracker.lon * weight;
        totalWeight += weight;
    });

    const lat = weightedLat / totalWeight;
    const lon = weightedLon / totalWeight;

    return {
        position: { lat, lon }
    };
}

// Función para validar latitud
function isValidLatitude(lat) {
    return lat >= -90 && lat <= 90;
}

// Función para validar longitud
function isValidLongitude(lon) {
    return lon >= -180 && lon <= 180;
}

