function getDistance(rssi) {
    const m = -0.01719;
    const b = -1.0341;
    return Math.pow(10, m * rssi + b);
}

function trilaterate(trackers, distances) {
    const math = global.get('math');
    const keys = Object.keys(trackers);
    if (keys.length < 3) throw new Error("Se requieren al menos 3 puntos");

    const originId = keys[0];
    const origin = trackers[originId];

    const toXY = (lat, lon) => {
        const R = 6371000;
        const dLat = (lat - origin.lat) * Math.PI / 180;
        const dLon = (lon - origin.lon) * Math.PI / 180;
        const x = R * dLon * Math.cos(origin.lat * Math.PI / 180);
        const y = R * dLat;
        return { x, y };
    };

    const toLatLon = (x, y) => {
        const R = 6371000;
        const dLat = y / R;
        const dLon = x / (R * Math.cos(origin.lat * Math.PI / 180));
        return {
            lat: origin.lat + dLat * 180 / Math.PI,
            lon: origin.lon + dLon * 180 / Math.PI
        };
    };

    const points = keys.map(id => {
        const { x, y } = toXY(trackers[id].lat, trackers[id].lon);
        return { x, y, r: distances[id], id };
    });

    if (points.length >= 4) {
        let A = [], b = [];
        const ref = points[0];
        for (let i = 1; i < points.length; i++) {
            const pi = points[i];
            A.push([2 * (pi.x - ref.x), 2 * (pi.y - ref.y)]);
            b.push(Math.pow(pi.r, 2) - Math.pow(ref.r, 2) + Math.pow(pi.x, 2) - Math.pow(ref.x, 2) + Math.pow(pi.y, 2) - Math.pow(ref.y, 2));
        }
        const At = math.transpose(A);
        const AtA = math.multiply(At, A);
        const Atb = math.multiply(At, b);
        const sol = math.lusolve(AtA, Atb);
        const x = sol[0][0] + ref.x;
        const y = sol[1][0] + ref.y;
        return { position: toLatLon(x, y) };
    } else {
        let sumX = 0, sumY = 0, totalWeight = 0;
        points.forEach(p => {
            const w = 1 / Math.max(p.r, 1);
            sumX += toXY(trackers[p.id].lat, trackers[p.id].lon).x * w;
            sumY += toXY(trackers[p.id].lat, trackers[p.id].lon).y * w;
            totalWeight += w;
        });
        const x = sumX / totalWeight;
        const y = sumY / totalWeight;
        return { position: toLatLon(x, y) };
    }
}

