// Nodo Function
const DATALOG = msg.payload.uplink_message.decoded_payload.DATALOG;
const conteo = msg.payload.uplink_message.f_cnt
const equipo = msg.payload.end_device_ids.device_id

// Limpiar la cadena DATALOG para eliminar la coma adicional al final
const cleanedDATALOG = DATALOG.replace(/,\s*$/, '');
const newArray = JSON.parse('[' + cleanedDATALOG.replace(/\(/g, '').replace(/\)/g, '') + ']');

// Función para transformar los datos
function transformData(data) {
    let result = [];
    let seriesX = [];
    let seriesY = [];
    let seriesZ = [];

    data.forEach((item, index) => {
        seriesX.push({ series: "X", x: conteo + '.' + index + 1, y: item[0] });
        seriesY.push({ series: "Y", x: conteo + '.' + index + 1, y: item[1] });
        seriesZ.push({ series: "Z", x: conteo + '.' + index + 1, y: item[2] });
    });

    result = result.concat(seriesX, seriesY, seriesZ);
    return result;
}

// Transformar los datos
msg.topic = equipo;
msg.payload = transformData(newArray);
return msg;

