// Nodo de función para acumular datos y calcular el valor RMS

// Obtener los datos del payload
let data = msg.payload;
let equipo = msg.topic;

// Obtener la variable de contexto del flujo para almacenar los datos acumulados
let accumulatedData = flow.get('accumulatedData'+ equipo) || [];

// Agregar los nuevos datos a los datos acumulados
accumulatedData = accumulatedData.concat(data);

// Guardar los datos acumulados en el contexto del flujo
flow.set('accumulatedData'+ equipo, accumulatedData);

// Obtener o inicializar el tiempo de inicio
let startTime = flow.get('startTime' + equipo);
if (!startTime) {
    startTime = Date.now();
    flow.set('startTime' + equipo, startTime);
}

// Calcular el tiempo transcurrido desde el inicio de la acumulación
let currentTime = Date.now();
let elapsedTime = (currentTime - startTime) / 1000; // Tiempo en segundos

// Si han pasado 30 minutos (1800 segundos), calcular el RMS
if (elapsedTime >= 1800) {
    // Calcular el valor RMS para cada eje
    function calculateRMS(values) {
        let sumOfSquares = values.reduce((sum, value) => sum + value * value, 0);
        return Math.sqrt(sumOfSquares / values.length);
    }

    // Separar los datos por ejes
    let xValues = accumulatedData.filter(item => item.series === 'X').map(item => item.y);
    let yValues = accumulatedData.filter(item => item.series === 'Y').map(item => item.y);
    let zValues = accumulatedData.filter(item => item.series === 'Z').map(item => item.y);

    // Calcular los valores RMS por eje
    let rmsX = calculateRMS(xValues);
    let rmsY = calculateRMS(yValues);
    let rmsZ = calculateRMS(zValues);

    // Calcular el valor RMS combinado
    let rmsTotal = Math.sqrt(rmsX * rmsX + rmsY * rmsY + rmsZ * rmsZ);

    // Obtener la fecha y hora actual en el formato correcto
    let fecha = new Date().toISOString().slice(0, 19).replace('T', ' ');

    // Crear el payload de respuesta con los valores RMS y la fecha
    msg.payload = {
        rmsX: rmsX,
        rmsY: rmsY,
        rmsZ: rmsZ,
        rmsTotal: rmsTotal,
        fecha: fecha,
        equipo: equipo
    };

    // Guardar los datos del payload en una variable local llamada vibracion001
    flow.set('vibracion' + equipo, msg.payload);

    // Reiniciar los datos acumulados y el tiempo de inicio
    flow.set('accumulatedData' + equipo, []);
    flow.set('startTime' + equipo, Date.now());

    return msg;
} else {
    // Si no han pasado 30 minutos, no enviar ningún mensaje
    return null;
}

