/**
 * Entrada esperada (desde Join):
 * msg.payload = {
 *   "ns=4;s=Traca_Transfo1": { d_and_t, OF_transfo, cycle_time, filling_time, mini_vacuum, qt_oil_intro, SP_qt_oil_intro, filling_type_level, filling_type_vol, filling_output },
 *   "ns=4;s=Traca_Transfo2": { ... },
 *   ...
 * }
 * Salida: array de puntos para nodo "influxdb batch" (InfluxDB v2)
 */

const measurement = "trafos";     // Cambia si quieres otro nombre
const equipo = "Campana c1";         // Tag fijo

// Si necesitas filtrar/renombrar campos, ajústalo aquí
const FIELD_ALLOWLIST = null; // p.ej. ["cycle_time","filling_time","mini_vacuum", ...] o déjalo null para enviar todos

// Helper: extraer "trafo1" de "ns=4;s=Traca_Transfo1"
function trafoFromNodeId(nodeId) {
    const m = /Transfo(\d+)/i.exec(nodeId || "");
    return m ? `trafo${m[1]}` : (nodeId || "trafo");
}

// Helper: normalizar nombre de campo para Influx (evitar puntos/espacios)
function sanitizeFieldName(k) {
    return String(k).replace(/\s+/g, "_").replace(/[.]/g, "_");
}

// Helper: decidir timestamp del punto (null => que lo ponga Influx)
function parseTimestamp(d_and_t) {
    if (!d_and_t) return null;
    // Ignorar el mínimo "1601-01-01..." típico de OPC/PLC
    if (/^1601-01-01T00:00:00/.test(d_and_t)) return null;
    const t = Date.parse(d_and_t);
    return isNaN(t) ? null : new Date(t); // El nodo Influx acepta Date o epoch (según config precision)
}

const puntos = [];

for (const [nodeId, valores] of Object.entries(msg.payload || {})) {
    if (!valores || typeof valores !== "object") continue;

    const trafo = trafoFromNodeId(nodeId);
    const ts = parseTimestamp(valores.d_and_t);

    const fields = {};
    for (const [k, v] of Object.entries(valores)) {
        if (k === "d_and_t") continue; // no lo metas como field, ya lo usamos como timestamp
        if (FIELD_ALLOWLIST && !FIELD_ALLOWLIST.includes(k)) continue;

        const key = sanitizeFieldName(k);

        // Casteo básico: números/booleanos, y strings tal cual
        if (typeof v === "number" || typeof v === "boolean") {
            fields[key] = v;
        } else if (v === null || v === undefined || v === "") {
            // omitir nulos/vacíos
        } else if (!isNaN(Number(v))) {
            fields[key] = Number(v);
        } else {
            fields[key] = String(v);
        }
    }

    // Influx requiere al menos 1 field
    if (Object.keys(fields).length === 0) continue;

    const punto = {
        measurement,
        tags: { equipo, trafo },
        fields
    };

    // Solo añade timestamp si lo tenemos (si no, lo pondrá Influx)
    if (ts) punto.timestamp = ts;

    puntos.push(punto);
}

msg.payload = puntos;
return msg;

/**
 * Convierte el objeto de valores unido por el Join en un array de puntos
 * para el nodo "influxdb batch" (InfluxDB v2).
 *
 * Espera:
 *   msg.payload = {
 *     "ns=4;s=ValVacuum": Number,
 *     "ns=4;s=ValDew_point_Temp": Number,
 *     "ns=4;s=ValDew_point": Number,
 *     "ns=4;s=ValPPMW_MAS1": Number,
 *     "ns=4;s=ValPPMW_MAS2": Number,
 *     "ns=4;s=Flow_Filling_MAS1": Number,
 *     "ns=4;s=Flow_Filling_MAS2": Number,
 *     "ns=4;s=Cycle_Time": Number
 *   }
 *
 * Sale:
 *   msg.payload = [
 *     {
 *       measurement: "campana",
 *       tags: { equipo: "puesto3" },
 *       fields: { vacuum, dew_point_temp, dew_point, ppmw_mas1, ppmw_mas2, flow_fill_mas1, flow_fill_mas2, cycle_time }
 *       // opcional: timestamp
 *     }
 *   ]
 */

const measurement = "campana";
const tags = { equipo: "C1" };

// Mapeo NodeId -> nombre de campo
const MAP = {
    "ns=4;s=ValVacuum": "Vacio_camara",
    "ns=4;s=ValDew_point_Temp": "Temp_cond_vacio",
    "ns=4;s=ValDew_point": "Humedad_relativa_cond_vacio",
    "ns=4;s=ValPPMW_MAS1": "ppm_mas1_llenado",
    "ns=4;s=ValPPMW_MAS2": "ppm_mas2_llenado",
    "ns=4;s=Flow_Filling_MAS1": "caudad_llenado_mas1",
    "ns=4;s=Flow_Filling_MAS2": "caudad_llenado_mas2",
    "ns=4;s=Cycle_Time": "cycle_time"
};

const fields = {};
for (const [nodeId, valor] of Object.entries(msg.payload || {})) {
    const campo = MAP[nodeId] || nodeId; // si aparece algo nuevo, usa el nodeId como fallback
    if (valor === null || valor === undefined || valor === "") continue;

    // Cast numérico si procede
    const num = Number(valor);
    fields[campo] = Number.isFinite(num) ? num : valor;
}

// Asegúrate de que hay al menos un campo
if (Object.keys(fields).length === 0) {
    node.warn("No hay campos válidos para escribir en Influx.");
    return null;
}

// Si quisieras fijar un timestamp específico, podrías añadir:
// const punto = { measurement, tags, fields, timestamp: new Date() };
const punto = { measurement, tags, fields };

msg.payload = [punto];
return msg;

let data = Array.isArray(msg.payload) ? msg.payload : [];
let ids = data.map(item => item.ID_NFabricacion);

// Si no hay IDs, avisamos
if (ids.length === 0) {
    node.warn("No se encontraron IDs en la respuesta");
}

// Formato correcto para el endpoint
msg.payload = { matriculas: ids };

return msg;

// Entrada: msg.payload = [porcentaje, litros]
// Salida 1: InfluxDB Batch
// Salida 2: WebSocket (objeto JSON) + guarda caché

const arr = Array.isArray(msg.payload) ? msg.payload : [];
const porcentaje = Number(arr[0]);
const litros = Number(arr[1]);

if (!Number.isFinite(porcentaje) || !Number.isFinite(litros)) {
    node.warn("Lectura no válida: " + JSON.stringify(msg.payload));
    return null;
}

const ts = Date.now();
const ultimo = {
    measurement: "Reserva_blanco",
    plc: "C1",
    address: "D200",
    porcentaje,
    litros,
    ts
};

// Cachear último valor en contexto de flujo
flow.set("reserva_blanco_last", ultimo);

// Mensaje para InfluxDB (batch)
const influxMsg = {
    topic: "Reserva_blanco",
    payload: [{
        measurement: "Reserva_blanco",
        tags: { plc: "C1", address: "D200" },
        fields: { porcentaje, litros }
        // timestamp: new Date(ts) // opcional si quieres timestamp local
    }]
};

// Mensaje para WebSocket (se envía a todos; un RBE aguas abajo evitará duplicados)
const wsMsg = {
    payload: ultimo
};

return [influxMsg, wsMsg];

// Si el cliente envía 'get' o 'subscribe', devolver el último valor sólo a ese cliente
// sin disparar nueva lectura al PLC.

const pl = msg.payload;
const isGet = (typeof pl === 'string' && /^(get|subscribe)$/i.test(pl)) ||
              (pl && typeof pl === 'object' && /^(get|subscribe)$/i.test(pl.cmd));

if (!isGet) {
    return null;
}

const last = flow.get("reserva_blanco_last");
if (!last) {
    // Nada cacheado aún
    return null;
}

// Enviar de vuelta sólo a ese cliente copiando _session
return {
    _session: msg._session,
    payload: last
};

let data = msg.payload;
let influxData = [];
data.forEach(o=>{
    if((typeof o.data) != 'object') {
        let obj = {
            measurement: o.topic,
        fields: {
                value: (typeof o.data) == 'string' ? o.data : o.data
            },

        };
        influxData.push(obj);
    }
});
msg.payload = influxData;
return msg;

let data = msg.payload;
let influxData = [];
data.forEach(o=>{
    if((typeof o.data) != 'object') {
        let obj = {
            measurement: o.topic,
        fields: {
                value: (typeof o.data) == 'string' ? o.data : o.data
            },

        };
        influxData.push(obj);
    }
});
msg.payload = influxData;
return msg;

let data = msg.payload;
let influxData = [];
data.forEach(o=>{
    if((typeof o.data) != 'object') {
        let obj = {
            measurement: o.topic,
        fields: {
                value: (typeof o.data) == 'string' ? o.data : o.data
            },

