let arr = msg.payload;

// LOW y HIGH (posiciones 1 y 2)
let low = arr[1];
let high = arr[2];

// Convertir a 32 bits
let value32 = (high << 16) + low;

// Eliminar las posiciones 1 y 2
arr.splice(1, 2);

// Insertar el nuevo valor de 32 bits en la posición 1
arr.splice(1, 0, value32);

msg.payload = arr;
return msg;

// Espera msg.payload como array con esta estructura:
// 0: status
// 1: matricula (32 bits)
// 2: liquido (0 ACEITE MINERAL, 1 PARYOL AGRILEC 6312, 2 ESTER NATURAL, 3 ESTER NATURAL)
// 3: via
// 4: presion
// 5: obviar
// 6: litros
// 7: obviar
// 8: obviar

const arr = Array.isArray(msg.payload) ? msg.payload : [];

if (arr.length < 7) {
    node.warn("Payload no tiene la longitud esperada.");
    return null; // corta el flujo si no hay datos suficientes
}

// Mapeo de código -> texto para 'liquido'
const liquidos = {
    0: "ACEITE MINERAL",
    1: "PARYOL AGRILEC 6312",
    2: "ESTER NATURAL",
    3: "ESTER NATURAL"
};

const status = Number(arr[0]) || 0;
const matricula = Number(arr[1]) || 0;
const liquidoCodigo = Number(arr[2]) || 0;
const via = Number(arr[3]) || 0;
const presion = Number(arr[4]) || 0;
const litros = Number(arr[6]) || 0;

// Si llega un código no contemplado, enviamos el código como string
const liquidoTexto = Object.prototype.hasOwnProperty.call(liquidos, liquidoCodigo)
  ? liquidos[liquidoCodigo]
  : String(liquidoCodigo);

// Objeto final con los nombres que necesitas
const body = {
    status: status,
    matricula: matricula,
    liquido: liquidoTexto,   // <- TEXTO
    via: via,
    presion: presion,
    litros: litros,
    tipo_registro: "Sobrepresión"
};

// Cabeceras para enviar JSON
msg.headers = {
    "Content-Type": "application/json",
    "Accept": "application/json"
    // Si necesitas token:
    // "Authorization": "Bearer TU_TOKEN"
};

// IMPORTANTE: tu controlador espera req.body[0], así que enviamos un ARRAY con el objeto
msg.payload = [body];

// (Opcional) conserva el array original para depurar:
msg.original = arr;

return msg;

msg.statusCode = 204; // No Content
msg.headers = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization'
};
return msg;

// 1) Leer datos y guardar estado inicial
const body = msg.payload;
const matricula = body?.matricula || msg.req?.body?.matricula || null;

flow.set('sobrepresionC2', {
  status: 'IN_PROGRESS',
  result: null,
  matricula
});

// 2) RESPUESTA: hay que conservar msg.res del http in.
//    Creamos un mensaje de respuesta clonando el msg de entrada.
const resp = { ...msg };  // <- mantiene msg.req y msg.res

resp.statusCode = 202; // Accepted
resp.headers = {
  ...resp.headers,
  'content-type': 'application/json',
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization'
};
resp.payload = { ok: true, status: 'IN_PROGRESS' };

// 3) Mensaje de trabajo para la rama PLC (¡sin msg.res!)
const work = {
  payload: body,
  matricula
};

return [resp, work];

/*
 Espera msg.payload como array, p.ej: [valor32, ...]
 Convierte payload[0] 32-bit en [high16, low16, ...]
*/
let combined = (msg.payload?.[0] >>> 0);
let high = combined & 0xFFFF;
let low = (combined >>> 16) & 0xFFFF;
msg.payload = [high, low, ...(Array.isArray(msg.payload) ? msg.payload.slice(1) : [])];
return msg;

/**
 * Guardar estado final en flow a partir de:
 * msg.payload = [matricula32, presion, statusPLC]
 * La temperatura NO se recibe desde PLC (la gestionas en el front).
 */
try {
  if (!Array.isArray(msg.payload) || msg.payload.length < 3) {
    node.warn('Payload inesperado en finales: ' + JSON.stringify(msg.payload));
    flow.set('sobrepresionC2', {
      status: 'ERROR',
      result: { error: 'Payload final incompleto' },
      matricula: flow.get('sobrepresionC2')?.matricula || null
    });
    return null;
  }

  // Orden según tu confirmación: [matricula, presion, status]
  const matricula = (Number(msg.payload[0]) >>> 0);       // unsigned 32
  const presion   = Number(msg.payload[1]);               // entero (escala /10 en Angular)
  const statusPLC = (Number(msg.payload[2]) & 0xFFFF) >>> 0; // unsigned 16

  // Persistimos estado para el endpoint de status
  flow.set('sobrepresionC2', {
    status: 'OK',
    result: {
      presion: presion,        // 👈 sin escalar; en Angular haces /10
      statusPLC: statusPLC
    },
    matricula: matricula       // opcional, útil para trazas
  });

  return null; // no responder HTTP aquí

} catch (e) {
  node.error('Excepción en finales: ' + (e?.message || e));
  flow.set('sobrepresionC2', {
    status: 'ERROR',
    result: { error: 'Excepción al procesar lectura final' },
    matricula: flow.get('sobrepresionC2')?.matricula || null
  });
  return null;
}

flow.set('sobrepresionC2', {
  status: 'ERROR',
  result: { error: msg.error?.message || 'Fallo PLC/Comunicaciones' },
  matricula: flow.get('sobrepresionC2')?.matricula || null
});
return null;

msg.statusCode = 204;
msg.headers = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization'
};
return msg;

// Leer matrícula (opcional)
const matricula = msg.req?.query?.matricula;

// Leer estado guardado por el flujo de inicio
const state = flow.get('sobrepresionC2') || { status: 'IDLE', result: null, matricula: null };

msg.statusCode = 200;
msg.headers = {
  'content-type': 'application/json',
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization'
};

msg.payload = {
  ok: true,
  linea: 'C2',
  matricula: matricula || state.matricula,
  status: state.status, // 'IN_PROGRESS' | 'OK' | 'ERROR' | 'IDLE'
  presion: state.result?.presion,
  statusPLC: state.result?.statusPLC,
  temperatura: state.result?.temperatura,
  ts: new Date().toISOString()
};

return msg;

