/**
 * Normaliza lecturas OPC:
 * - msg.topic: quita "ns=4;s="
 * - msg.payload: desenvuelve DataValue/Variant típico OPC UA
 */

function cleanTopic(full) {
  const i = (full || "").indexOf("s=");
  return i >= 0 ? full.substring(i + 2) : (full || "");
}

function unwrapOpcValue(v) {
  // { value: { value: X } } o { value: X }
  if (v && typeof v === "object") {
    if ("value" in v) {
      const vv = v.value;
      if (vv && typeof vv === "object" && "value" in vv) return vv.value;
      return vv;
    }
  }
  return v;
}

msg.topic = cleanTopic(msg.topic);
msg.payload = unwrapOpcValue(msg.payload);
return msg;

/**
 * Influx (tracking) por transporte — tipado según UDT_TRACKING
 *
 * ENTRADA (después del Join):
 * msg.payload = {
 *   "DATA_VM01_1": { codigo: "...", destino: 1, ... },
 *   "DATA_VM02":   { ... },
 *   ...
 * }
 *
 * SALIDA:
 * msg.payload = [
 *   { measurement:"tracking", tags:{linea:"C1", transporte:"DATA_VM01_1"}, fields:{...} },
 *   ...
 * ]
 */

// --------------------- helpers ---------------------
function cleanTransporte(t) {
    const s = String(t || "");
    const idx = s.indexOf("s=");
    return idx >= 0 ? s.substring(idx + 2) : s;
}

function unwrapOpcValue(v) {
    // Por si algún campo viene como { value:{value:X} } o { value:X }
    if (v && typeof v === "object" && "value" in v) {
        const vv = v.value;
        if (vv && typeof vv === "object" && "value" in vv) return vv.value;
        return vv;
    }
    return v;
}

function asString(v) {
    v = unwrapOpcValue(v);
    if (v === null || v === undefined) return "";
    return String(v);
}

function asBool(v) {
    v = unwrapOpcValue(v);
    if (v === null || v === undefined) return false;
    if (typeof v === "boolean") return v;
    if (typeof v === "number") return v !== 0;
    const s = String(v).trim().toLowerCase();
    return (s === "true" || s === "1" || s === "yes" || s === "y" || s === "on");
}

function asInt(v) {
    v = unwrapOpcValue(v);
    if (v === null || v === undefined || v === "") return 0;
    if (typeof v === "number") return Number.isFinite(v) ? (v | 0) : 0; // int32
    const n = Number(String(v).trim().replace(",", "."));
    return Number.isFinite(n) ? (n | 0) : 0;
}

function asFloat(v) {
    v = unwrapOpcValue(v);
    if (v === null || v === undefined || v === "") return 0.0;
    if (typeof v === "number") return Number.isFinite(v) ? nRound(v) : 0.0;
    const n = Number(String(v).trim().replace(",", "."));
    return Number.isFinite(n) ? nRound(n) : 0.0;
}

function nRound(x) {
    // opcional: evita floats “largos” por ruido binario
    return Math.round(x * 1000) / 1000;
}

