// Tipos según tu tabla:
// STRING[256], int, DINT, REAL, BOOL
const UDT = [
    ["codigo", "STRING"],
    ["destino", "INT"],
    ["acuñado_ok", "BOOL"],
    ["t_acuñado", "DINT"],
    ["cierre_ok", "BOOL"],
    ["t_cierre", "DINT"],
    ["tapas_ok", "BOOL"],
    ["t_tapas", "DINT"],
    ["conexionado_ok", "BOOL"],
    ["t_conexionado", "DINT"],
    ["test_ok", "BOOL"],
    ["test_nok", "BOOL"],
    ["t_test", "DINT"],
    ["entrada_horno", "BOOL"],
    ["aceite_litros", "INT"],
    ["aceite_temperatura", "INT"],
    ["aceite_tipo", "INT"],
    ["t_horno", "DINT"],
    ["th_horno", "INT"],
    ["ta_entrada_horno", "REAL"],
    ["salida_horno", "BOOL"]
];

function castByType(v, t) {
    switch (t) {
        case "STRING": return asString(v);
        case "BOOL": return asBool(v);
        case "DINT": return asInt(v);   // int32
        case "INT": return asInt(v);   // int16 en PLC, pero en Influx lo guardamos como int
        case "REAL": return asFloat(v); // float
        default: return unwrapOpcValue(v);
    }
}

