    for (const [fieldName, fieldType] of UDT) {
        const rawVal = struct && typeof struct === "object" ? struct[fieldName] : undefined;
        const casted = castByType(rawVal, fieldType);

        // Evita undefined (Influx no lo admite); decide qué hacer con strings vacíos:
        // aquí guardamos siempre (puedes comentar si no quieres strings vacíos)
        fields[fieldName] = casted;
    }

    // Seguridad: Influx requiere al menos 1 field
    if (Object.keys(fields).length === 0) fields.raw = "";

    points.push({
        measurement: "tracking",
        tags: {
            transporte: transporte
        },
        fields: fields
    });
}

